package com.ginga.naviai.auth.dto;

import java.time.Instant;

public class UserResponse {
    private Long id;
    private String username;
    private String email;
    private String displayName;
    private Instant createdAt;
    private boolean isAdmin;

    public UserResponse() {}

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getUsername() { return username; }
    public void setUsername(String username) { this.username = username; }
    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }
    public String getDisplayName() { return displayName; }
    public void setDisplayName(String displayName) { this.displayName = displayName; }
    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }
    public boolean isAdmin() { return isAdmin; }
    public void setIsAdmin(boolean isAdmin) { this.isAdmin = isAdmin; }
}

package com.ginga.naviai.user.controller;

import com.ginga.naviai.auth.dto.UserResponse;
import com.ginga.naviai.user.service.UserService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/v1/users")
public class UserController {

    private final UserService userService;

    @Autowired
    public UserController(UserService userService) {
        this.userService = userService;
    }

    @GetMapping("/me")
    public ResponseEntity<UserResponse> getCurrentUser(Authentication authentication) {
        if (authentication == null || authentication.getName() == null || authentication.getName().trim().isEmpty()) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }

        Long userId;
        try {
            userId = Long.valueOf(authentication.getName());
        } catch (NumberFormatException ex) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }

        UserResponse res = userService.getCurrentUser(userId);
        boolean isAdmin = authentication.getAuthorities().stream()
            .anyMatch(a -> "ROLE_ADMIN".equals(a.getAuthority()));
        res.setIsAdmin(isAdmin);
        return ResponseEntity.ok(res);
    }
}

package com.ginga.naviai.user.controller;

import com.ginga.naviai.auth.dto.UserResponse;
import com.ginga.naviai.config.SecurityConfig;
import com.ginga.naviai.user.exception.UserNotFoundException;
import com.ginga.naviai.user.service.UserService;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.BeforeEach;
import org.springframework.security.test.context.support.WithMockUser;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.context.annotation.Import;
import org.springframework.test.web.servlet.MockMvc;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletRequest;
import jakarta.servlet.ServletResponse;
import static org.mockito.ArgumentMatchers.any;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import java.util.List;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.authentication;
import static org.mockito.Mockito.doAnswer;

import static org.mockito.Mockito.when;
import static org.mockito.Mockito.doThrow;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@WebMvcTest(UserController.class)
@AutoConfigureMockMvc
public class UserControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private UserService userService;

    @MockBean
    private com.ginga.naviai.auth.filter.JwtAuthenticationFilter jwtAuthenticationFilter;

    @BeforeEach
    void setup() throws Exception {
        // Make the mocked filter pass the request through so controller is reached
        doAnswer(invocation -> {
            ServletRequest req = invocation.getArgument(0);
            ServletResponse res = invocation.getArgument(1);
            FilterChain chain = invocation.getArgument(2);
            chain.doFilter(req, res);
            return null;
        }).when(jwtAuthenticationFilter).doFilter(any(ServletRequest.class), any(ServletResponse.class), any(FilterChain.class));
    }

    @Test
    void getCurrentUser_unauthorized_returns401() throws Exception {
        // no authentication attached to request
        SecurityContextHolder.clearContext();
        mockMvc.perform(get("/api/v1/users/me"))
            .andExpect(status().isUnauthorized());
    }

    @Test
    @WithMockUser(username = "1")
    void getCurrentUser_success_returns200() throws Exception {
        UsernamePasswordAuthenticationToken auth = new UsernamePasswordAuthenticationToken("1", null, List.of(new SimpleGrantedAuthority("ROLE_USER")));
        UserResponse res = new UserResponse();
        res.setId(1L);
        res.setUsername("testuser");
        res.setEmail("test@ginga.info");
        res.setDisplayName("Test User");
        res.setCreatedAt(java.time.Instant.parse("2026-02-07T10:20:30Z"));

        when(userService.getCurrentUser(1L)).thenReturn(res);
        try {
            mockMvc.perform(get("/api/v1/users/me").with(authentication(auth)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id").value(1))
                .andExpect(jsonPath("$.username").value("testuser"))
                        .andExpect(jsonPath("$.displayName").value("Test User"))
                        .andExpect(jsonPath("$.createdAt").value("2026-02-07T10:20:30Z"))
                        .andExpect(jsonPath("$.isAdmin").value(false));
        } finally {
            SecurityContextHolder.clearContext();
        }
    }

    @Test
    @WithMockUser(username = "1", roles = {"ADMIN"})
    void getCurrentUser_admin_returnsIsAdminTrue() throws Exception {
        UsernamePasswordAuthenticationToken auth = new UsernamePasswordAuthenticationToken("1", null, List.of(new SimpleGrantedAuthority("ROLE_ADMIN")));
        UserResponse res = new UserResponse();
        res.setId(1L);
        res.setUsername("adminuser");
        res.setEmail("admin@ginga.info");
        res.setDisplayName("Admin User");
        res.setCreatedAt(java.time.Instant.parse("2026-02-07T10:20:30Z"));

        when(userService.getCurrentUser(1L)).thenReturn(res);
        try {
            mockMvc.perform(get("/api/v1/users/me").with(authentication(auth)))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.id").value(1))
                .andExpect(jsonPath("$.username").value("adminuser"))
                .andExpect(jsonPath("$.isAdmin").value(true));
        } finally {
            SecurityContextHolder.clearContext();
        }
    }

    @Test
    @WithMockUser(username = "99")
    void getCurrentUser_notFound_returns404() throws Exception {
        UsernamePasswordAuthenticationToken auth = new UsernamePasswordAuthenticationToken("99", null, List.of(new SimpleGrantedAuthority("ROLE_USER")));
        doThrow(new UserNotFoundException("User not found"))
            .when(userService).getCurrentUser(99L);

        try {
            mockMvc.perform(get("/api/v1/users/me").with(authentication(auth)))
                .andExpect(status().isNotFound());
        } finally {
            SecurityContextHolder.clearContext();
        }
    }

    @Test
    @WithMockUser(username = "invalid")
    void getCurrentUser_invalidSubject_returns401() throws Exception {
        UsernamePasswordAuthenticationToken auth = new UsernamePasswordAuthenticationToken("invalid", null, List.of(new SimpleGrantedAuthority("ROLE_USER")));
        try {
            mockMvc.perform(get("/api/v1/users/me").with(authentication(auth)))
                .andExpect(status().isUnauthorized());
        } finally {
            SecurityContextHolder.clearContext();
        }
    }

    @Test
    @WithMockUser(username = " ")
    void getCurrentUser_blankSubject_returns401() throws Exception {
        UsernamePasswordAuthenticationToken auth = new UsernamePasswordAuthenticationToken(" ", null, List.of(new SimpleGrantedAuthority("ROLE_USER")));
        try {
            mockMvc.perform(get("/api/v1/users/me").with(authentication(auth)))
                .andExpect(status().isUnauthorized());
        } finally {
            SecurityContextHolder.clearContext();
        }
    }

    @Test
    @WithMockUser(username = "1")
    void getCurrentUser_serviceError_returns500() throws Exception {
        UsernamePasswordAuthenticationToken auth = new UsernamePasswordAuthenticationToken("1", null, List.of(new SimpleGrantedAuthority("ROLE_USER")));
        doThrow(new RuntimeException("unexpected"))
            .when(userService).getCurrentUser(1L);

        try {
            mockMvc.perform(get("/api/v1/users/me").with(authentication(auth)))
                .andExpect(status().isInternalServerError());
        } finally {
            SecurityContextHolder.clearContext();
        }
    }
}

package com.ginga.naviai.dashboard.dto;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.List;

/**
 * ダッシュボードのサマリー情報を返すDTO
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class DashboardSummaryResponse {
    /** 総投稿数 */
    private long totalPosts;

    /** 今週の投稿数 */
    private long weeklyPosts;

    /** 承認待ち件数 */
    private long pendingApprovals;

    /** 週次アクティビティ（週開始日時・件数） */
    private java.util.List<WeeklyActivity> weeklyActivity;

    /** 人気タグ上位 */
    private List<TagSummary> topTags;

    /** 新着記事 */
    private List<ArticleSummary> recentArticles;

    /** おすすめ記事 */
    private List<ArticleSummary> recommendedArticles;

    @Data
    @AllArgsConstructor
    @NoArgsConstructor
    public static class TagSummary {
        private String tag;
        private long count;
    }

    @Data
    @Builder
    @AllArgsConstructor
    @NoArgsConstructor
    public static class ArticleSummary {
        private Long id;
        private String title;
        private String authorDisplayName;
        private java.time.Instant publishedAt;
        private long likeCount;
    }

    @Data
    @AllArgsConstructor
    @NoArgsConstructor
    public static class WeeklyActivity {
        private java.time.Instant weekStart;
        private long count;
    }
}

package com.ginga.naviai.knowledge.repository;

import com.ginga.naviai.knowledge.entity.Knowledge;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.time.Instant;
import java.util.List;

@Repository
public interface KnowledgeRepository extends JpaRepository<Knowledge, Long> {

    long countByDeletedFalse();

    long countByCreatedAtAfterAndDeletedFalse(Instant start);

    long countByStatusAndDeletedFalse(String status);

    @Query(value = "SELECT t.name as tag, COUNT(kt.knowledge_id) as count " +
                   "FROM tag t " +
                   "JOIN knowledge_tag kt ON t.id = kt.tag_id " +
                   "GROUP BY t.name " +
                   "ORDER BY count DESC " +
                   "LIMIT :limit", nativeQuery = true)
    List<Object[]> findTopTags(@Param("limit") int limit);

    @Query("SELECT k FROM Knowledge k WHERE k.status = 'published' AND k.deleted = false ORDER BY k.publishedAt DESC")
    List<Knowledge> findRecentArticles(Pageable pageable);

    @Query(value = "SELECT k.id, k.title, u.display_name, k.published_at, COUNT(l.id) as like_count " +
                   "FROM knowledge k " +
                   "LEFT JOIN users u ON k.author_id = u.id " +
                   "LEFT JOIN \"like\" l ON k.id = l.knowledge_id " +
                   "WHERE k.status = 'published' AND k.is_deleted = false " +
                   "GROUP BY k.id, u.display_name " +
                   "ORDER BY like_count DESC, k.published_at DESC " +
                   "LIMIT :limit", nativeQuery = true)
    List<Object[]> findTopRecommendedArticles(@Param("limit") int limit);

    long countByCreatedAtBetweenAndDeletedFalse(Instant start, Instant end);
}

package com.ginga.naviai.dashboard.service;

import com.ginga.naviai.dashboard.dto.DashboardSummaryResponse;
import com.ginga.naviai.knowledge.entity.Knowledge;
import com.ginga.naviai.knowledge.repository.KnowledgeRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.sql.Timestamp;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.ArrayList;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
public class DashboardServiceImpl implements DashboardService {

    private final KnowledgeRepository knowledgeRepository;

    @Override
    @Transactional(readOnly = true)
    public DashboardSummaryResponse getSummary() {
        long totalPosts = knowledgeRepository.countByDeletedFalse();
        
        Instant weekAgo = Instant.now().minus(7, ChronoUnit.DAYS);
        long weeklyPosts = knowledgeRepository.countByCreatedAtAfterAndDeletedFalse(weekAgo);
        
        long pendingApprovals = knowledgeRepository.countByStatusAndDeletedFalse("pending");
        
        List<Object[]> topTagsData = knowledgeRepository.findTopTags(5);
        List<DashboardSummaryResponse.TagSummary> topTags = topTagsData.stream()
            .map(row -> new DashboardSummaryResponse.TagSummary((String) row[0], ((Number) row[1]).longValue()))
            .collect(Collectors.toList());

        // 新着記事 (Top 5)
        List<Knowledge> recentEntities = knowledgeRepository.findRecentArticles(PageRequest.of(0, 5));
        List<DashboardSummaryResponse.ArticleSummary> recentArticles = recentEntities.stream()
            .map(k -> DashboardSummaryResponse.ArticleSummary.builder()
                .id(k.getId())
                .title(k.getTitle())
                .authorDisplayName(k.getAuthor() != null ? k.getAuthor().getDisplayName() : "不明")
                .publishedAt(k.getPublishedAt())
                .likeCount(0) // 簡略化のため新着一覧では0
                .build())
            .collect(Collectors.toList());

        // おすすめ記事 (Top 5 by Likes)
        List<Object[]> recommendedData = knowledgeRepository.findTopRecommendedArticles(5);
        List<DashboardSummaryResponse.ArticleSummary> recommendedArticles = recommendedData.stream()
            .map(row -> DashboardSummaryResponse.ArticleSummary.builder()
                .id(((Number) row[0]).longValue())
                .title((String) row[1])
                .authorDisplayName((String) row[2])
                .publishedAt(row[3] != null ? ((Timestamp) row[3]).toInstant() : null)
                .likeCount(((Number) row[4]).longValue())
                .build())
            .collect(Collectors.toList());

        // 週次アクティビティ（直近4週）
        int weeks = 4;
        Instant now = Instant.now();
        List<DashboardSummaryResponse.WeeklyActivity> weeklyActivity = new ArrayList<>();
        for (int i = weeks - 1; i >= 0; i--) {
            Instant start = now.minus((long)(i + 1) * 7, ChronoUnit.DAYS);
            Instant end = now.minus((long)i * 7, ChronoUnit.DAYS);
            long count = knowledgeRepository.countByCreatedAtBetweenAndDeletedFalse(start, end);
            weeklyActivity.add(new DashboardSummaryResponse.WeeklyActivity(start, count));
        }

        return DashboardSummaryResponse.builder()
            .totalPosts(totalPosts)
            .weeklyPosts(weeklyPosts)
            .pendingApprovals(pendingApprovals)
            .weeklyActivity(weeklyActivity)
            .topTags(topTags)
            .recentArticles(recentArticles)
            .recommendedArticles(recommendedArticles)
            .build();
    }
}

